function motifBlock(g,x0,y0,w,h,base,acc,typ,mo){
  g.noStroke(); g.fill(base[0],base[1]*100,base[2]*100); g.rect(x0,y0,w,h);
  // weft float lines (horizontal grain)
  g.stroke(0,0,0,10); g.strokeWeight(1); for(let yy=y0+2;yy<y0+h;yy+=Math.max(3,h/26)) g.line(x0,yy,x0+w,yy); g.noStroke();
