  const cx=x0+w/2, cy=y0+h/2, s=Math.min(w,h)*0.5*mo;
  if(typ===0){ // stacked diamonds
    for(let k=-1;k<=1;k++){ g.push(); g.translate(cx,cy+k*h*0.28); g.rotate(Math.PI/4); g.rect(-s*0.5,-s*0.5,s,s); g.pop(); }
  } else if(typ===1){ // zigzag comb
    g.stroke(acc[0],acc[1]*100,acc[2]*100); g.strokeWeight(Math.max(2,w*0.06)); g.noFill();
    g.beginShape(); for(let xx=0;xx<=6;xx++) g.vertex(x0+ w*xx/6, cy + (xx&1? -h*0.22:h*0.22)); g.endShape(); g.noFill(); g.noStroke();
  } else if(typ===2){ // checker eyes
    const n=3; const cw=w/(n+1); for(let a=0;a<n;a++) for(let b=0;b<2;b++){ g.rect(x0+cw*(a+0.6), cy-h*0.2+b*h*0.32, cw*0.7, cw*0.7); }
  } else { // hollow squares (nkyimkyim)
    g.stroke(acc[0],acc[1]*100,acc[2]*100); g.strokeWeight(Math.max(2,w*0.05)); g.noFill();
    g.rect(cx-s*0.7,cy-s*0.7,s*1.4,s*1.4); g.rect(cx-s*0.35,cy-s*0.35,s*0.7,s*0.7); g.noStroke();
  }
}

